action.command:
python3 -c "
import json,re,sys
try: d=json.load(sys.stdin)
except Exception: sys.exit(0)
cmd=json.dumps(d.get('toolInput') or d.get('tool_input') or d, ensure_ascii=False)
if not re.search(r'git\s+(add|commit|push)', cmd): sys.exit(0)
bad=[p for p in [r'\.env(\b|[^.])', r'\.p8\b', r'\.pem\b', r'AuthKey', r'id_rsa', r'\.jsonl\b'] if re.search(p, cmd)]
if bad:
    print('Остановлено: команда затрагивает файлы, похожие на секреты (' + ', '.join(bad) + '). Репозиторий публичный — добавляйте файлы по именам.', file=sys.stderr)
    sys.exit(2)
if re.search(r'git\s+add\s+(-A|--all|\.\s*$)', cmd):
    print(json.dumps({'hookSpecificOutput':{'permissionDecision':'ask','permissionDecisionReason':'git add -A в папке с .env и ключами Apple. Подтвердите или добавьте файлы по именам.'}}))
sys.exit(0)
"
